CREATE TYPE "UserRole" AS ENUM ('MOTHER','MIDWIFE','ADMIN');
CREATE TYPE "UserStatus" AS ENUM ('PENDING','ACTIVE','DISABLED','BLOCKED','ARCHIVED');
CREATE TABLE "User" ("id" UUID PRIMARY KEY,"publicId" UUID NOT NULL,"phoneNumber" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "UserRole" NOT NULL,"status" "UserStatus" NOT NULL DEFAULT 'ACTIVE',"phoneVerifiedAt" TIMESTAMP(3),"failedLoginCount" INTEGER NOT NULL DEFAULT 0,"lockedUntil" TIMESTAMP(3),"lastLoginAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"deactivatedAt" TIMESTAMP(3));
CREATE UNIQUE INDEX "User_publicId_key" ON "User"("publicId"); CREATE UNIQUE INDEX "User_phoneNumber_key" ON "User"("phoneNumber"); CREATE INDEX "User_role_status_idx" ON "User"("role","status"); CREATE INDEX "User_lockedUntil_idx" ON "User"("lockedUntil");
CREATE TABLE "MotherProfile" ("id" UUID PRIMARY KEY,"userId" UUID NOT NULL UNIQUE,"fullName" TEXT NOT NULL,"preferredName" TEXT,"dateOfBirth" TIMESTAMP(3),"profileCompleted" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "MotherProfile_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "MidwifeProfile" ("id" UUID PRIMARY KEY,"userId" UUID NOT NULL UNIQUE,"fullName" TEXT NOT NULL,"phoneNumber" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "MidwifeProfile_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE); CREATE INDEX "MidwifeProfile_active_idx" ON "MidwifeProfile"("active");
CREATE TABLE "AdminProfile" ("id" UUID PRIMARY KEY,"userId" UUID NOT NULL UNIQUE,"fullName" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AdminProfile_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "RefreshSession" ("id" UUID PRIMARY KEY,"userId" UUID NOT NULL,"tokenHash" TEXT NOT NULL UNIQUE,"expiresAt" TIMESTAMP(3) NOT NULL,"revokedAt" TIMESTAMP(3),"deviceName" TEXT,"ipAddress" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "RefreshSession_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE); CREATE INDEX "RefreshSession_userId_revokedAt_idx" ON "RefreshSession"("userId","revokedAt"); CREATE INDEX "RefreshSession_expiresAt_idx" ON "RefreshSession"("expiresAt");
CREATE TABLE "ConsentDocument" ("id" UUID PRIMARY KEY,"documentType" TEXT NOT NULL,"version" TEXT NOT NULL,"title" TEXT NOT NULL,"content" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT false,"effectiveAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL); CREATE UNIQUE INDEX "ConsentDocument_documentType_version_key" ON "ConsentDocument"("documentType","version"); CREATE INDEX "ConsentDocument_active_effectiveAt_idx" ON "ConsentDocument"("active","effectiveAt");
CREATE TABLE "UserConsent" ("id" UUID PRIMARY KEY,"userId" UUID NOT NULL,"documentId" UUID NOT NULL,"agreedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"withdrawnAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "UserConsent_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE,CONSTRAINT "UserConsent_documentId_fkey" FOREIGN KEY("documentId") REFERENCES "ConsentDocument"("id")); CREATE UNIQUE INDEX "UserConsent_userId_documentId_key" ON "UserConsent"("userId","documentId");
CREATE TABLE "AuditLog" ("id" UUID PRIMARY KEY,"actorUserId" UUID,"actorRole" "UserRole","action" TEXT NOT NULL,"entityType" TEXT,"entityId" TEXT,"result" TEXT NOT NULL,"requestId" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_actorUserId_fkey" FOREIGN KEY("actorUserId") REFERENCES "User"("id") ON DELETE SET NULL); CREATE INDEX "AuditLog_createdAt_idx" ON "AuditLog"("createdAt"); CREATE INDEX "AuditLog_actorUserId_createdAt_idx" ON "AuditLog"("actorUserId","createdAt"); CREATE INDEX "AuditLog_action_result_idx" ON "AuditLog"("action","result");
CREATE TABLE "SystemSetting" ("id" UUID PRIMARY KEY,"key" TEXT NOT NULL,"value" JSONB NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL); CREATE UNIQUE INDEX "SystemSetting_key_key" ON "SystemSetting"("key");
